package com.complaintbox.controller; import com.complaintbox.entity.*; import com.complaintbox.repository.*; import com.complaintbox.service.*; import jakarta.servlet.http.HttpSession; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/profile") public class ProfileController{final ResidentRepository repo;final AuthService auth;public ProfileController(ResidentRepository r,AuthService a){repo=r;auth=a;}@PatchMapping Object update(@RequestBody Map<String,String>x,HttpSession s){Resident r=repo.findById(auth.residentId(s)).orElseThrow();r.setName(x.get("name"));r.setRoomNumber(x.get("roomNumber"));r.setHostelBlock(x.get("hostelBlock"));r.setPhone(x.get("phone"));repo.save(r);return Map.of("id",r.getId(),"name",r.getName(),"email",r.getEmail(),"studentId",Objects.toString(r.getResidentId(),""),"roomNumber",Objects.toString(r.getRoomNumber(),""),"hostelBlock",Objects.toString(r.getHostelBlock(),""),"phone",Objects.toString(r.getPhone(),""),"role","user");}}
